from revised_analyzer.sample_qc import Sample
import pytest

def load_fasta(filepath):
    """Parses a wrapped FASTA file into parallel lists of IDs and unwrapped sequences."""

    seq_ids = []
    sequences = []
    current_chunks = []

    with open(filepath, "r") as file:
        for line in file:
            line = line.strip()

            if not line:
                continue

            if line.startswith(">"):

                if current_chunks:
                    sequences.append("".join(current_chunks))
                    current_chunks = []

                # Extract the sequence ID
                seq_ids.append(line[1:].split()[0])

            else:
                current_chunks.append(line)

    # Append the final sequence
    if current_chunks:
        sequences.append("".join(current_chunks))

    return seq_ids, sequences

