def test_sample_import():
    assert Sample is not None

def test_sample_initialization():
    sample = Sample("sample1", "ATGCC")
    assert sample.sample_id == "sample1"
    assert sample.sample_seq == "ATGCC"

@pytest.mark.parametrize("seq_id, seq, expected_gc", zip(SEQ_IDS, SEQUENCES, EXPECTED_GC), ids=SEQ_IDS)
def test_gc_content(seq_id, seq, expected_gc):
    sample = Sample(seq_id, seq)
    assert pytest.approx(sample.get_gc_content(), abs=0.01) == expected_gc

@pytest.mark.parametrize("seq_id, seq, expected_rc", zip(SEQ_IDS, SEQUENCES, EXPECTED_REV_COMPS), ids=SEQ_IDS)
def test_reverse_complement(seq_id, seq, expected_rc):
    sample = Sample(seq_id, seq)
    assert sample.get_reverse_complement() == expected_rc

@pytest.mark.parametrize("seq_id, seq, expected_orf", zip(SEQ_IDS, SEQUENCES, EXPECTED_ORFS), ids=SEQ_IDS)
def test_find_orfs(seq_id, seq, expected_orf):
    sample = Sample(seq_id, seq)
    orf = sample.get_longest_ORF_seq()
    assert orf == expected_orf

